package glitch

import data.glitch_lib

# Set of insecure protocols that lack integrity protection
insecure_protocols := {"HTTP", "FTP", "Telnet", "TCP"}

# Set of insecure backend types
insecure_backends := {"http"}

# Function to check if an attribute indicates missing integrity check
check_missing_integrity(attr) {
    # Check for explicit flags disabling integrity
    attr.name == "checksum"
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    attr.name == "integrity"
    attr.value.ir_type == "String"
    regex.match("(?i)none|disabled", attr.value.value)
} else {
    attr.name == "authentication"
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    attr.name == "signature"
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    attr.name == "encrypt"
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    attr.name == "ssl_verify"
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    attr.name == "gpg_check"
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    attr.name == "allow_unauthenticated"
    attr.value.ir_type == "Boolean"
    attr.value.value == true
}

# Function to check if a protocol attribute uses insecure protocol
check_insecure_protocol(attr) {
    attr.name == "protocol"
    attr.value.ir_type == "String"
    insecure_protocols[_] == attr.value.value
} else {
    attr.name == "backend"
    attr.value.ir_type == "String"
    insecure_backends[_] == attr.value.value
}

# Function to check if checksum/hash is missing when required
check_missing_checksum(attr) {
    attr.name == "checksum"
    attr.value.ir_type == "Null"
} else {
    attr.name == "source_hash"
    attr.value.ir_type == "Null"
} else {
    attr.name == "hashing_algorithm"
    attr.value.ir_type == "Null"
} else {
    # Check if checksum attribute is missing entirely from required resources
    # This is handled by checking the presence of required attributes in the main rule
    false
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Get all attributes for the atomic unit
    attrs := glitch_lib.all_attributes(node)

    # Check for insecure protocol configurations
    attr := attrs[_]
    check_insecure_protocol(attr)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Communication channel lacks integrity protection. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Get all attributes for the atomic unit
    attrs := glitch_lib.all_attributes(node)

    # Check for explicit integrity disabling flags
    attr := attrs[_]
    check_missing_integrity(attr)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Integrity verification mechanism is disabled or missing. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Get all attributes for the atomic unit
    attrs := glitch_lib.all_attributes(node)

    # Check for missing checksums in storage/package resources
    attr := attrs[_]
    check_missing_checksum(attr)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Cryptographic hash/checksum is missing for data integrity. (CWE-353)"
    }
}

