package glitch

import data.glitch_lib

weakness_keywords := {"protocol", "checksum", "integrity", "authentication", "signature", "use_proxy_protocol", "encrypt", "backend", "versioning", "allow_unauthenticated", "gpg_check", "source_hash", "transport", "ssl_verify", "integrity_protection", "dnssec_validation"}

vulnerable_values := {"HTTP", "FTP", "Telnet", "UDP", "false", "none", "disabled", "tcp", "http"}

check_value(val) {
    val.ir_type == "String"
    vulnerable_values[_] == val.value
} else {
    val.ir_type == "Boolean"
    val.value == false
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    weakness_keywords[_] == attr.name
    check_value(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Configurations establish data transmission or storage without enabling integrity verification mechanisms. (CWE-353)"
    }
}
